import { NextRequest, NextResponse } from 'next/server'
import { supabase, isConfigured } from '@/lib/supabase'

// GET /api/reactions?friendIndex=0&visitorId=xxx
// → { counts: { '共感': 3, 'びっくり': 1, ... }, mine: ['共感'] }
export async function GET(req: NextRequest) {
  if (!isConfigured) return NextResponse.json({ counts: {}, mine: [] })

  const { searchParams } = new URL(req.url)
  const friendIndex = Number(searchParams.get('friendIndex') ?? 0)
  const visitorId   = searchParams.get('visitorId') ?? ''

  const { data, error } = await supabase
    .from('reactions')
    .select('reaction, visitor_id')
    .eq('friend_index', friendIndex)

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })

  const counts: Record<string, number> = {}
  const mine: string[] = []

  for (const row of data ?? []) {
    counts[row.reaction] = (counts[row.reaction] ?? 0) + 1
    if (row.visitor_id === visitorId) mine.push(row.reaction)
  }

  return NextResponse.json({ counts, mine })
}

// POST /api/reactions  body: { friendIndex, reaction, visitorId }
// → toggle: insert if not exists, delete if exists
export async function POST(req: NextRequest) {
  if (!isConfigured) return NextResponse.json({ ok: false, reason: 'not_configured' })

  const { friendIndex, reaction, visitorId } = await req.json()
  if (!visitorId || !reaction) {
    return NextResponse.json({ error: 'missing fields' }, { status: 400 })
  }

  // check existing
  const { data: existing } = await supabase
    .from('reactions')
    .select('id')
    .eq('friend_index', friendIndex)
    .eq('reaction', reaction)
    .eq('visitor_id', visitorId)
    .single()

  if (existing) {
    // delete (un-react)
    await supabase.from('reactions').delete().eq('id', existing.id)
    return NextResponse.json({ action: 'removed' })
  } else {
    // insert (react)
    await supabase.from('reactions').insert({ friend_index: friendIndex, reaction, visitor_id: visitorId })
    return NextResponse.json({ action: 'added' })
  }
}
